<?php

declare(strict_types=1);

namespace JOetjen\Cooper\Tests\Pipeline;

use JOetjen\Cooper\Pipeline\Display;
use JOetjen\Cooper\Value\CooperAtom;
use JOetjen\Cooper\Value\CooperInteger;
use JOetjen\Cooper\Value\CooperTuple;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

/**
 * `Display` renders values exactly as the Elixir original's
 * `to_string/1` does, so one CASC document interpolates to the same text
 * in every port.
 */
final class DisplayTest extends TestCase
{
    /**
     * Pairs generated by running Elixir's own `to_string/1` over random
     * and edge-case floats.
     *
     * @return list<array{float, string}>
     */
    public static function elixirFloats(): array
    {
        return [
            [0.0, '0.0'],
            [0.004, '0.004'],
            [0.00642, '0.00642'],
            [0.065, '0.065'],
            [0.30000000000000004, '0.30000000000000004'],
            [0.3333333333333333, '0.3333333333333333'],
            [0.5, '0.5'],
            [0.927, '0.927'],
            [1.0e-7, '1.0e-7'],
            [1.0e100, '1.0e100'],
            [1.0e22, '1.0e22'],
            [1.0e3, '1.0e3'],
            [100.0, '100.0'],
            [123.456, '123.456'],
            [1393037822660.323, '1393037822660.323'],
            [1679853786.43, '1679853786.43'],
            [2.5e-300, '2.5e-300'],
            [242869330.387, '242869330.387'],
            [244677683664.3, '244677683664.3'],
            [2825.01426, '2825.01426'],
            [3.748538431280954e17, '3.748538431280954e17'],
            [3.872900949107423e16, '3.872900949107423e16'],
            [3216867480242.087, '3216867480242.087'],
            [32634885.5, '32634885.5'],
            [3283.804892, '3283.804892'],
            [330261.610959, '330261.610959'],
            [355488685892832.8, '355488685892832.8'],
            [45907052.06, '45907052.06'],
            [4616.11568, '4616.11568'],
            [4667817927342.536, '4667817927342.536'],
            [50400444063630.945, '50400444063630.945'],
            [53.5, '53.5'],
            [538840038752.0661, '538840038752.0661'],
            [579348648.28363, '579348648.28363'],
            [5851871001054154.0, '5851871001054154.0'],
            [601719070672.2273, '601719070672.2273'],
            [645681.964, '645681.964'],
            [68607.44038, '68607.44038'],
            [7253.424992, '7253.424992'],
            [8.159155777585529e19, '8.159155777585529e19'],
            [80838.7, '80838.7'],
            [9.007199254740992e15, '9.007199254740992e15'],
            [9.220818367401453e20, '9.220818367401453e20'],
            [93387.6735, '93387.6735'],
            [996061942446147.0, '996061942446147.0'],
            [12000.0, '1.2e4'],
            [1010.0, '1010.0'],
            [10100.0, '1.01e4'],
            [1234567890123456.0, '1234567890123456.0'],
            [999999999999999.0, '999999999999999.0'],
            [1.0e14, '1.0e14'],
            [0.0001, '0.0001'],
            [1.5e-4, '1.5e-4'],
            [0.0015, '0.0015'],
            [125.0, '125.0'],
            [-0.0, '-0.0'],
            [-1000.0, '-1.0e3'],
        ];
    }

    #[DataProvider('elixirFloats')]
    public function testFloatsMatchElixir(float $value, string $expected): void
    {
        self::assertSame($expected, Display::float($value));
    }

    public function testFloatRenderingRoundTripsForRandomValues(): void
    {
        mt_srand(2718);
        for ($i = 0; $i < 2000; $i++) {
            $value = (mt_rand() / mt_getrandmax()) * (10 ** mt_rand(-30, 30)) * (mt_rand(0, 1) === 0 ? 1 : -1);
            $text = Display::float($value);

            self::assertSame($value, (float) $text, $text);
            self::assertMatchesRegularExpression('/\A-?\d+\.\d+(e-?\d+)?\z/', $text);
        }
    }

    public function testScalarsAndAtoms(): void
    {
        self::assertSame('nil', Display::toString(null));
        self::assertSame('true', Display::toString(true));
        self::assertSame('42', Display::toString(42));
        self::assertSame('inf', Display::toString(INF));
        self::assertSame('-inf', Display::toString(-INF));
        self::assertSame('18446744073709551616', Display::toString(new CooperInteger('18446744073709551616')));
        self::assertSame('info', Display::toString(CooperAtom::of('info')));
    }

    public function testCollectionsHaveNoStringForm(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessage('cannot interpolate {1, 2} into a string');

        Display::toString(new CooperTuple([1, 2]));
    }

    public function testInspect(): void
    {
        self::assertSame('"a\"b"', Display::inspect('a"b'));
        self::assertSame(':info', Display::inspect(CooperAtom::of('info')));
        self::assertSame('[1, "x", nil]', Display::inspect([1, 'x', null]));
        self::assertSame('%{"k" => 1.0}', Display::inspect(['k' => 1.0]));
    }
}
